import type { GatewayContext, ActionResult } from './types.ts';

// json() helper — returns ActionResult (main index.ts converts to Response)
const json = (body: unknown, status = 200): ActionResult => ({ status, body });

export async function handleClaimsAction(action: string, ctx: GatewayContext): Promise<ActionResult | null> {
  // Narrowed to what this module actually uses — the wider destructure was
  // boilerplate from the split out of index.ts, and tripped noUnusedLocals once
  // claimPolicyLink.test.ts pulled this file into the typecheck program.
  const { db, params, caller } = ctx;

  switch (action) {
    case 'get_my_claims': {
        // FIX v1.50.0: match both owner ids (legacy accounts have
        // sp_users.id ≠ auth id; older claims were written with auth id).
        const { data, error } = await db
          .from('sp_claims')
          .select('*')
          .in('user_id', caller.ownerIds)
          .is('deleted_at', null)
          .order('created_at', { ascending: false })
          .limit(100);
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'submit_claim': {
        // FIX: previously this dropped 7 of 10 fields the UI sends, AND never set agent_id.
        // Now accepts the full claim payload and derives agent_id from the linked policy order.
        const claimType = String(params.claim_type ?? params.product_type ?? 'VEHICLE').toUpperCase();
        const description = String(params.description ?? params.chronology ?? '').slice(0, 5000);

        // Carried beside insertRow, not inside it, and written in a separate
        // best-effort statement after the claim exists.
        //
        // sp_claims.insurer_id arrives in migration 20261023120000. If this
        // function were deployed before that migration ran, an insert naming
        // the column would fail *entirely* — every claim submission rejected,
        // not just the insurer link. Deploy order between a migration and a
        // function is a human step, and it has already slipped once here.
        // Written separately, the worst case if the column is missing is that
        // the link is absent: the claim itself is still filed correctly, and
        // the link starts working the moment the migration runs, with no
        // redeploy. Server-derived from the order, like agent_id/client_id —
        // never from the payload.
        let linkedInsurerId: string | null = null;

        const insertRow: Record<string, unknown> = {
          user_id: caller.ownerId,
          claim_type: claimType,
          description,
          location: String(params.location ?? '').slice(0, 500),
          amount_estimated: Number(params.amount_estimated ?? 0),
          status: 'SUBMITTED',
          // NEW fields (previously dropped):
          client_name:    params.client_name    ? String(params.client_name).slice(0, 200)    : null,
          policy_number:  params.policy_number  ? String(params.policy_number).slice(0, 100)  : null,
          product_type:   params.product_type   ? String(params.product_type).slice(0, 50)    : claimType,
          chronology:     params.chronology     ? String(params.chronology).slice(0, 5000)    : null,
          photos:         params.photos         ? params.photos                               : null,
          incident_date:  params.incident_date ?? params.date ?? null,
        };

        // ── Claim photo fraud analysis: pull TRUSTED, server-computed results ──
        // We never trust fraud_score/fraud_verdict/photo_reports if the client
        // sends them directly — that would let the exact fraudster this
        // feature targets simply claim "CLEAN" regardless of what
        // analyze-claim-photos actually found. Instead, the client only sends
        // back the analysisId it got from that edge function; we look up the
        // row it staged (service_role write), verify it belongs to this
        // caller, hasn't expired, and hasn't already been consumed by another
        // claim, then use ONLY the staged values.
        let stagedAnalysis: Record<string, any> | null = null;
        if (params.analysis_id) {
          const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000).toISOString();
          const { data: staged } = await db
            .from('sp_claim_photo_analyses')
            .select('*')
            .eq('id', String(params.analysis_id))
            .in('user_id', caller.ownerIds)
            .is('consumed_at', null)
            .gte('created_at', oneHourAgo)
            .maybeSingle();
          if (staged) {
            stagedAnalysis = staged;
            insertRow.photo_urls = staged.photo_urls ?? null;
            insertRow.ai_fraud_score = staged.fraud_score ?? null;
            insertRow.ai_fraud_verdict = staged.fraud_verdict ?? null;
            insertRow.ai_photo_reports = staged.photo_reports ?? null;
            insertRow.ai_analyzed_at = staged.created_at ?? new Date().toISOString();
            // photos (legacy jsonb column) mirrors photo_urls when present so
            // old UI code paths that still read `photos` keep working.
            if (!insertRow.photos && staged.photo_urls) insertRow.photos = staged.photo_urls;
          }
        }

        // Derive agent_id + policy_id from linked policy order (if policy_number or policy_id provided)
        if (params.policy_id) {
          insertRow.policy_id = String(params.policy_id);
          const { data: linkedOrder } = await db.from('sp_policy_orders')
            .select('agent_id, client_id, insurer_id')
            .eq('id', String(params.policy_id))
            .maybeSingle();
          if (linkedOrder) {
            // FIX v1.42.0: verify the caller owns this policy (as agent_id OR client_id).
            // Previously any authenticated user could link a claim to any policy.
            const lo = linkedOrder as any;
            const isOwner = caller.ownerIds.includes(lo.agent_id) || caller.ownerIds.includes(lo.client_id);
            if (!isOwner && !caller.isAdmin) {
              return json({ error: 'Polis tidak ditemukan atau bukan milik Anda.' }, 403);
            }
            insertRow.agent_id = lo.agent_id;
            if (lo.client_id) insertRow.client_id = lo.client_id;
            linkedInsurerId = lo.insurer_id ?? null;
          }
        } else if (params.policy_number) {
          // Match the real policy number as well as the internal order number.
          //
          // What the customer holds is the policy number off the insurer's PDF
          // (sp_policy_orders.policy_number, written by insurer_upload_policy).
          // Matching order_number alone meant a claim filed with the genuine
          // policy number found nothing, so it was stored with no policy_id and
          // no agent_id — invisible to the agent and impossible to route to the
          // insurer. `limit(1)` rather than maybeSingle(): the two columns live
          // in different namespaces, so a value could in principle hit both.
          //
          // The reference is stripped to [A-Za-z0-9._/-] before it reaches the
          // .or() string. An .or() filter is parsed by PostgREST, not bound as
          // a parameter, so a comma or parenthesis in the value would rewrite
          // the predicate rather than be matched by it. Real order and policy
          // numbers only use these characters.
          const ref = String(params.policy_number).replace(/[^A-Za-z0-9._/-]/g, '').slice(0, 100);
          const { data: linkedOrders } = ref
            ? await db.from('sp_policy_orders')
                .select('id, agent_id, client_id, insurer_id')
                .or(`order_number.eq.${ref},policy_number.eq.${ref}`)
                .limit(1)
            : { data: null };
          const linkedOrder = (linkedOrders ?? [])[0] ?? null;
          if (linkedOrder) {
            // FIX v1.42.0: verify ownership here too
            const lo = linkedOrder as any;
            const isOwner = caller.ownerIds.includes(lo.agent_id) || caller.ownerIds.includes(lo.client_id);
            if (!isOwner && !caller.isAdmin) {
              return json({ error: 'Polis tidak ditemukan atau bukan milik Anda.' }, 403);
            }
            insertRow.policy_id = lo.id;
            insertRow.agent_id  = lo.agent_id;
            if (lo.client_id) insertRow.client_id = lo.client_id;
            linkedInsurerId = lo.insurer_id ?? null;
          }
        }

        const { data, error } = await db
          .from('sp_claims')
          .insert(insertRow)
          .select()
          .single();
        if (error) return json({ error: error.message }, 400);

        // Link the claim to its insurer. Deliberately after the insert and
        // deliberately not awaited for success: see linkedInsurerId above. A
        // failure here means the insurer portal cannot filter this claim yet,
        // which is recoverable; a failure inside the insert would have meant no
        // claim at all.
        if (linkedInsurerId) {
          db.from('sp_claims')
            .update({ insurer_id: linkedInsurerId })
            .eq('id', (data as any).id)
            .then(() => {}, () => {});
        }

        // ── Consume the staged photo analysis (prevents reuse across multiple
        // claims) and record the perceptual hashes for future duplicate checks
        if (stagedAnalysis) {
          db.from('sp_claim_photo_analyses').update({ consumed_at: new Date().toISOString() }).eq('id', stagedAnalysis.id).then(() => {}, () => {});
          const hashes: (string | null)[] = Array.isArray(stagedAnalysis.photo_hashes) ? stagedAnalysis.photo_hashes : [];
          const urls: string[] = Array.isArray(stagedAnalysis.photo_urls) ? stagedAnalysis.photo_urls : [];
          const hashRows = urls
            .map((url, i) => ({ photo_hash: hashes[i], photo_url: url }))
            .filter(r => r.photo_hash != null)
            .map(r => ({ photo_hash: r.photo_hash, source_type: 'CLAIM', source_id: (data as any).id, photo_url: r.photo_url }));
          if (hashRows.length > 0) db.from('sp_photo_hashes').insert(hashRows).then(() => {}, () => {});
        }

        // ── Operator/admin in-app notification ──────────────────────────────
        db.from('sp_admin_notifications').insert({
          type: 'NEW_CLAIM',
          title: 'Klaim Baru Diajukan',
          body: `${String((data as any).claim_type ?? 'Klaim')} · ${String((data as any).client_name ?? 'Nasabah')} · Rp ${Number((data as any).amount_estimated ?? 0).toLocaleString('id-ID')}`,
          read: false,
          metadata: { claim_id: (data as any).id, user_id: caller.authId, agent_id: insertRow.agent_id ?? null },
        }).then(() => {}, () => {});

        // NEW: distinct fraud-alert notification when photo verification wasn't clean
        if (insertRow.ai_fraud_verdict && insertRow.ai_fraud_verdict !== 'CLEAN') {
          db.from('sp_admin_notifications').insert({
            type: 'CLAIM_FRAUD_ALERT',
            title: insertRow.ai_fraud_verdict === 'REJECTED' ? 'Klaim Berisiko Tinggi — Foto Mencurigakan' : 'Klaim Perlu Tinjauan — Foto Ditandai',
            body: `${String((data as any).client_name ?? 'Nasabah')} · Skor fraud: ${insertRow.ai_fraud_score}/100 · ${String((data as any).claim_number ?? (data as any).id)}`,
            read: false,
            metadata: { claim_id: (data as any).id, user_id: caller.authId, fraud_score: insertRow.ai_fraud_score, fraud_verdict: insertRow.ai_fraud_verdict },
          }).then(() => {}, () => {});
        }

        // NEW: Notify the agent (if linked) that one of their customers filed a claim
        if (insertRow.agent_id) {
          db.from('sp_notifications').insert({
            agent_id: String(insertRow.agent_id),
            type: 'NEW_CLAIM',
            title: 'Klaim Baru dari Nasabah',
            body: `${String((data as any).client_name ?? 'Nasabah')} mengajukan klaim ${String((data as any).claim_type ?? '')} senilai Rp ${Number((data as any).amount_estimated ?? 0).toLocaleString('id-ID')}.`,
            read: false,
            metadata: { claim_id: (data as any).id, user_id: caller.authId },
          }).then(() => {}, () => {});
        }
        return json({ data });
      }

    case 'admin_list_claims': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        let q = db.from('sp_claims').select('*').is('deleted_at', null).order('created_at', { ascending: false }).limit(Number(params.limit ?? 200));
        if (params.status) q = q.eq('status', params.status);
        const { data, error } = await q;
        if (error) return json({ error: error.message }, 400);
        return json({ data });
      }

    case 'admin_update_claim': {
        if (!caller.isAdmin) return json({ error: 'Forbidden: admin only' }, 403);
        if (!params.claim_id || !params.status) return json({ error: 'claim_id and status required' }, 400);
        const VALID = ['SUBMITTED', 'UNDER_REVIEW', 'APPROVED', 'REJECTED', 'PAID'];
        if (!VALID.includes(String(params.status))) return json({ error: 'Invalid status' }, 400);
        const updates: Record<string, unknown> = { status: params.status, updated_at: new Date().toISOString() };
        if (params.adjuster_notes) updates.adjuster_notes = String(params.adjuster_notes).slice(0, 5000);

        // Fetch current row for notification targeting
        const { data: current } = await db.from('sp_claims')
          .select('id, user_id, agent_id, claim_type, status, amount_estimated')
          .eq('id', String(params.claim_id))
          .maybeSingle();

        const { data, error } = await db.from('sp_claims').update(updates).eq('id', params.claim_id).select().maybeSingle();
        if (error) return json({ error: error.message }, 400);

        // NEW: Notify the customer (and agent) about the claim status change
        const statusLabels: Record<string, string> = {
          UNDER_REVIEW: 'Sedang Ditinjau',
          APPROVED:     'Disetujui',
          REJECTED:     'Ditolak',
          PAID:         'Dibayarkan',
          SUBMITTED:    'Diajukan',
        };
        const newLabel = statusLabels[String(params.status)] ?? String(params.status);
        const cur = current as any;
        if (cur?.user_id) {
          db.from('sp_notifications').insert({
            agent_id: String(cur.user_id),
            type: 'CLAIM_UPDATE',
            title: `Klaim ${newLabel}`,
            body: `Status klaim ${String(cur.claim_type ?? '')} Anda telah diperbarui menjadi: ${newLabel}.${params.adjuster_notes ? ` Catatan: ${String(params.adjuster_notes).slice(0, 200)}` : ''}`,
            read: false,
            metadata: { claim_id: cur.id, status: params.status, adjuster_notes: params.adjuster_notes ?? null },
          }).then(() => {}, () => {});
        }
        if (cur?.agent_id && cur.agent_id !== cur.user_id) {
          db.from('sp_notifications').insert({
            agent_id: String(cur.agent_id),
            type: 'CLAIM_UPDATE',
            title: `Klaim Nasabah ${newLabel}`,
            body: `Klaim ${String(cur.claim_type ?? '')} untuk nasabah Anda telah diperbarui menjadi: ${newLabel}.`,
            read: false,
            metadata: { claim_id: cur.id, status: params.status },
          }).then(() => {}, () => {});
        }
        return json({ data });
      }

    default:
      return null; // Not handled by this module
  }
}

// clientLink.ts — menautkan sebuah order ke akun nasabahnya.
//
// ─────────────────────────────────────────────────────────────────────────────
// ATURAN PENCOCOKAN — baca sebelum melebarkannya
// ─────────────────────────────────────────────────────────────────────────────
//
// `sp_policy_orders.client_id` menentukan siapa yang boleh MELIHAT dan
// MENGKLAIM sebuah polis: `get_my_orders`, `get_my_payments`, `cancel_my_order`
// dan pemeriksaan kepemilikan di `submit_claim` semuanya bersandar padanya.
// Satu pencocokan yang salah berarti polis seseorang terlihat — dan bisa
// diklaim — oleh orang lain. Jadi aturan ini dipilih untuk salah ke arah
// "tidak menautkan apa pun", bukan "menautkan yang keliru".
//
// Penautan HANYA lewat email, dan harus cocok persis:
//
//   1. Email di order harus berbentuk email yang wajar.
//   2. Harus ada TEPAT SATU baris `sp_users` yang cocok. Nol baris, atau dua
//      ke atas, tidak menautkan apa pun.
//   3. Email baris itu harus sama persis dengan email di order setelah
//      keduanya di-lowercase — bukan sekadar "cocok menurut pola".
//   4. Peran baris itu harus CUSTOMER.
//   5. Tidak pernah menautkan ke id yang dikecualikan pemanggil — dipakai
//      supaya agen yang mengisi emailnya sendiri di kolom nasabah tidak
//      menjadi "client" atas ordernya sendiri, yang akan mengaburkan batas
//      antara agent_id dan client_id.
//
// Langkah 3 bukan pengulangan langkah 2. `%` dan `_` adalah wildcard LIKE,
// dan email di order datang dari payload klien, jadi `client_email: "%@gmail.com"`
// akan dicocokkan oleh `.ilike()` dengan nasabah mana pun. Wildcard-nya
// di-escape sebelum dikirim, DAN hasilnya dibandingkan lagi sebagai string di
// sini — pola yang melebar kena langkah 2 (lebih dari satu baris), dan pola
// yang kebetulan mengenai tepat satu baris kena langkah 3.
//
// ─────────────────────────────────────────────────────────────────────────────
// NOMOR TELEPON SENGAJA TIDAK DIPAKAI
// ─────────────────────────────────────────────────────────────────────────────
//
// Mencocokkan nomor telepon akan menautkan lebih banyak order — dan itu
// justru alasannya ditolak. Di pasar ini satu nomor sering dipakai bergantian
// dalam satu keluarga, ditulis dalam tiga format yang sama-sama sah (`08xx`,
// `+628xx`, `628xx`), dan agen kadang mengisi nomornya sendiri di kolom
// nasabah supaya OTP masuk ke dirinya. Ketiganya membuat pencocokan nomor
// jadi tebakan, dan yang ditebak di sini adalah hak baca atas sebuah polis.
//
// Order yang emailnya tidak cocok tetap menyimpan `client_email` apa adanya,
// jadi ia masih bisa tertaut nanti — lihat `linkOrdersToNewCustomer()`.

/** Minimal PostgREST client surface these helpers need. */
interface Db {
  from(table: string): any;
}

/** Escapes the LIKE wildcards `%` and `_` so an email is matched literally. */
function escapeLike(value: string): string {
  return value.replace(/[\\%_]/g, (c) => `\\${c}`);
}

/**
 * True for a string shaped like a single email address. Deliberately strict:
 * no spaces, no commas, exactly one `@`, and a dot in the domain.
 */
function looksLikeEmail(value: string): boolean {
  return /^[^\s@,]+@[^\s@,]+\.[^\s@,]+$/.test(value);
}

/** Lowercased, trimmed email, or null when it isn't one. */
export function normaliseEmail(raw: unknown): string | null {
  const email = String(raw ?? '').trim().toLowerCase();
  if (!email || email.length > 200 || !looksLikeEmail(email)) return null;
  return email;
}

/**
 * Resolves the `sp_users.id` of the CUSTOMER an order belongs to, from the
 * email captured on that order. Returns null unless every rule above holds.
 *
 * @param excludeIds ids that must never be returned — pass the caller's own
 *   ids so an agent cannot become the client of their own order.
 */
export async function findClientIdByEmail(
  db: Db,
  rawEmail: unknown,
  excludeIds: string[] = [],
): Promise<string | null> {
  const email = normaliseEmail(rawEmail);
  if (!email) return null;

  // limit(2) — the rule needs to know "exactly one", not "the first one".
  const { data: rows, error } = await db.from('sp_users')
    .select('id, email, role')
    .ilike('email', escapeLike(email))
    .limit(2);
  if (error || !Array.isArray(rows) || rows.length !== 1) return null;

  const row = rows[0] as { id?: unknown; email?: unknown; role?: unknown };
  if (String(row.email ?? '').trim().toLowerCase() !== email) return null;
  if (String(row.role ?? '').toUpperCase() !== 'CUSTOMER') return null;

  const id = String(row.id ?? '');
  if (!id || excludeIds.includes(id)) return null;
  return id;
}

/**
 * Attaches orders that were sold to this email before the customer had an
 * account. Called from ensure_profile when a CUSTOMER profile is created.
 *
 * This is the one place that writes `client_id` onto pre-existing orders. It is
 * narrow on purpose: the email comes from the caller's own verified session —
 * never from a request parameter — and only rows that are still unclaimed
 * (`client_id is null`) and not the new user's own agent rows are touched.
 *
 * Returns how many orders were linked. Best-effort: a failure here must never
 * fail the signup it runs inside.
 */
export async function linkOrdersToNewCustomer(
  db: Db,
  userId: string,
  rawEmail: unknown,
): Promise<number> {
  const email = normaliseEmail(rawEmail);
  if (!email || !userId) return 0;

  try {
    const { data, error } = await db.from('sp_policy_orders')
      .update({ client_id: userId, updated_at: new Date().toISOString() })
      .is('client_id', null)
      .neq('agent_id', userId)
      .ilike('client_email', escapeLike(email))
      .select('id');
    if (error || !Array.isArray(data)) return 0;
    return data.length;
  } catch {
    return 0;
  }
}
